<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {runtime} from './ipc';import type {McpConnection,McpView,McpResult,McpAction} from './generated/protocol';
const view=ref<McpView|null>(null),selected=ref(''),editing=ref(false),saving=ref(false),error=ref(''),id=ref(''),baseline=ref('');
const results=reactive<Record<string,McpResult>>({}),busy=reactive<Record<string,boolean>>({});
const blank=():McpConnection=>({type:'stdio',command:'',args:[],enabled:true,env:{},headers:{},disabledTools:[],startupTimeoutMs:20000,callTimeoutMs:60000});
const draft=ref<McpConnection>(blank()),args=ref(''),env=ref(''),headers=ref(''),enabledTools=ref(''),allowAll=ref(true),disabledTools=ref('');
const current=computed(()=>view.value?.connections[selected.value]);
const signature=()=>JSON.stringify([id.value,draft.value,args.value,env.value,headers.value,enabledTools.value,allowAll.value,disabledTools.value]);
const dirty=computed(()=>editing.value&&signature()!==baseline.value);
async function load(){error.value='';try{const r=await runtime.operation({method:'mcp_read'});if(r.kind==='mcp')view.value=r.data;}catch(e){error.value=String(e);}}
function edit(key:string){selected.value=key;id.value=key;draft.value=JSON.parse(JSON.stringify(view.value?.connections[key]??blank()));args.value=draft.value.type==='stdio'?draft.value.args.join('\n'):'';env.value=Object.entries(draft.value.env).map(([k,v])=>`${k}=${v.env}`).join('\n');headers.value=Object.entries(draft.value.headers).map(([k,v])=>`${k}=${v.env}`).join('\n');allowAll.value=draft.value.enabledTools===undefined;enabledTools.value=(draft.value.enabledTools??[]).join('\n');disabledTools.value=draft.value.disabledTools.join('\n');editing.value=true;baseline.value=signature();}
function refs(text:string){return Object.fromEntries(text.split('\n').filter(v=>v.trim()).map(line=>{const at=line.indexOf('=');if(at<1)throw new Error('引用格式为 名称=环境变量名');return [line.slice(0,at).trim(),{env:line.slice(at+1).trim()}];}));}
async function save(){if(!view.value)return false;saving.value=true;error.value='';try{const connections={...view.value.connections};if(selected.value&&selected.value!==id.value)delete connections[selected.value];const c=JSON.parse(JSON.stringify(draft.value)) as McpConnection;if(c.type==='stdio')c.args=args.value.split('\n').filter(Boolean);c.env=refs(env.value);c.headers=refs(headers.value);c.enabledTools=allowAll.value?undefined:enabledTools.value.split('\n').map(v=>v.trim()).filter(Boolean);c.disabledTools=disabledTools.value.split('\n').filter(Boolean);connections[id.value]=c;
 const r=await runtime.operation({method:'mcp_save',params:{revision:view.value.revision,connections}});if(r.kind!=='mcp')throw new Error('MCP 保存响应无效');view.value=r.data;selected.value=id.value;editing.value=false;return true;}catch(e){error.value=String(e);return false;}finally{saving.value=false;}}
async function remove(){if(!view.value)return;saving.value=true;error.value='';try{const connections={...view.value.connections};delete connections[selected.value];const r=await runtime.operation({method:'mcp_save',params:{revision:view.value.revision,connections}});if(r.kind==='mcp'){view.value=r.data;selected.value='';}}catch(e){error.value=String(e);}finally{saving.value=false;}}
async function control(server:string,action:McpAction){busy[server]=true;error.value='';try{const r=await runtime.operation({method:'mcp_control',params:{server,action}});if(r.kind==='mcp_result')results[server]=r.data;}catch(e){error.value=String(e);}finally{busy[server]=false;}}
function transport(type:string){draft.value=type==='stdio'?{...blank(),type:'stdio',command:'',args:[]}:{...blank(),type:'http',url:''};}
defineExpose({dirty,save,discard:()=>editing.value=false});onMounted(load);
</script>
<template><div class="panel"><p v-if="error" role="alert" class="failure">{{error}}</p><p v-if="saving" role="status">正在保存并等待相关调用结束后应用…</p>
 <form v-if="editing" @submit.prevent="save"><fieldset :disabled="saving"><label>连接 ID<input v-model="id" required pattern="[A-Za-z0-9_-]+"/></label><label>传输<select :value="draft.type" @change="transport(($event.target as HTMLSelectElement).value)"><option value="stdio">stdio</option><option value="http">Streamable HTTP</option></select></label><template v-if="draft.type==='stdio'"><label>命令<input v-model="draft.command" required/></label><label>参数（每行一个）<textarea v-model="args" rows="4"/></label><label>工作目录<input v-model="draft.cwd"/></label></template><label v-else>URL<input v-model="draft.url" type="url" required/></label><label class="check"><input v-model="draft.enabled" type="checkbox"/>启用</label><label>环境变量引用（名称=环境变量名）<textarea v-model="env" rows="3"/></label><label>HTTP Header 引用（Header=环境变量名）<textarea v-model="headers" rows="3"/></label><label>启动超时（毫秒）<input v-model.number="draft.startupTimeoutMs" type="number" min="1" max="120000"/></label><label>调用超时（毫秒）<input v-model.number="draft.callTimeoutMs" type="number" min="1" max="600000"/></label><label class="check"><input v-model="allowAll" type="checkbox"/>允许全部工具</label><label v-if="!allowAll">仅允许这些工具（每行一个；空列表禁用全部）<textarea v-model="enabledTools"/></label><label>禁用的工具（每行一个）<textarea v-model="disabledTools"/></label><div class="actions"><button type="submit">保存</button><button type="button" @click="editing=false">放弃编辑</button></div></fieldset></form>
 <template v-else><div class="actions"><button :disabled="saving" @click="edit('')">添加连接</button><button :disabled="saving" @click="load">重新读取</button></div><div class="resource-list"><button v-for="(connection,key) in view?.connections" :key="key" :class="{selected:selected===key}" @click="selected=String(key)">{{key}}<small>{{connection.type}} · {{connection.enabled?'启用':'停用'}}</small></button></div><div v-if="current" class="resource-detail"><p class="path">{{current.type==='stdio'?current.command:current.url}}</p><div class="actions"><button :disabled="saving" @click="edit(selected)">编辑</button><button :disabled="saving" @click="remove">删除配置</button><button :disabled="busy[selected]||!current.enabled" @click="control(selected,'inspect')">检查与工具清单</button><button :disabled="busy[selected]||!current.enabled" @click="control(selected,'reconnect')">重连</button><button :disabled="busy[selected]" @click="control(selected,'close')">关闭连接</button></div><p v-if="busy[selected]">操作待完成，正在等待连接…</p><p>{{results[selected]?.state}}</p><details v-for="tool in results[selected]?.tools" :key="tool.name"><summary>{{tool.name}}</summary><p>{{tool.description}}</p><pre>{{tool.schema}}</pre></details></div></template>
</div></template>
